using Commerce;

namespace Commerce.Tests;

[TestClass]
public class ShoppingCartTests
{
    private ShoppingCart _cart = null!;

    [TestInitialize]
    public void Setup() => _cart = new ShoppingCart();

    // --- Adding Items ---

    [TestMethod]
    public void AddItem_SingleItem_IncludedInTotal()
    {
        _cart.AddItem("SKU-1", 10.00m, 2);
        Assert.AreEqual(20.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void AddItem_MultipleItems_TotalSumsAll()
    {
        _cart.AddItem("A", 5.00m, 3);
        _cart.AddItem("B", 12.50m, 1);
        Assert.AreEqual(27.50m, _cart.GetTotal());
    }

    [TestMethod]
    public void AddItem_SameSkuTwice_BothCountedSeparately()
    {
        _cart.AddItem("A", 10.00m, 1);
        _cart.AddItem("A", 10.00m, 1);
        Assert.AreEqual(20.00m, _cart.GetTotal());
    }

    // --- Removing Items ---

    [TestMethod]
    public void RemoveItem_ExistingSku_ReturnsTrue()
    {
        _cart.AddItem("X", 5.00m, 1);
        Assert.IsTrue(_cart.RemoveItem("X"));
    }

    [TestMethod]
    public void RemoveItem_NonExistingSku_ReturnsFalse()
    {
        Assert.IsFalse(_cart.RemoveItem("NOPE"));
    }

    [TestMethod]
    public void RemoveItem_ExistingSku_ExcludedFromTotal()
    {
        _cart.AddItem("A", 10.00m, 1);
        _cart.AddItem("B", 5.00m, 2);
        _cart.RemoveItem("A");
        Assert.AreEqual(10.00m, _cart.GetTotal());
    }

    // --- GetTotal ---

    [TestMethod]
    public void GetTotal_EmptyCart_ReturnsZero()
    {
        Assert.AreEqual(0m, _cart.GetTotal());
    }

    [TestMethod]
    public void GetTotal_AfterAllItemsRemoved_ReturnsZero()
    {
        _cart.AddItem("A", 7.00m, 1);
        _cart.RemoveItem("A");
        Assert.AreEqual(0m, _cart.GetTotal());
    }

    // --- Promo Codes ---

    [TestMethod]
    public void ApplyPromoCode_ValidCode_ReturnsTrue()
    {
        _cart.RegisterPromoCode("SAVE10", 10);
        Assert.IsTrue(_cart.ApplyPromoCode("SAVE10"));
    }

    [TestMethod]
    public void ApplyPromoCode_InvalidCode_ReturnsFalse()
    {
        Assert.IsFalse(_cart.ApplyPromoCode("BOGUS"));
    }

    [TestMethod]
    public void ApplyPromoCode_CaseInsensitive()
    {
        _cart.RegisterPromoCode("SAVE10", 10);
        Assert.IsTrue(_cart.ApplyPromoCode("save10"));
    }

    [TestMethod]
    public void GetTotal_WithPromoCode_AppliesPercentDiscount()
    {
        _cart.AddItem("A", 100.00m, 1);
        _cart.RegisterPromoCode("HALF", 50);
        _cart.ApplyPromoCode("HALF");
        Assert.AreEqual(50.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void GetTotal_WithoutPromoCode_NoDiscount()
    {
        _cart.AddItem("A", 100.00m, 1);
        _cart.RegisterPromoCode("HALF", 50);
        Assert.AreEqual(100.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void GetTotal_PromoCodeOnMultipleItems()
    {
        _cart.AddItem("A", 20.00m, 2);
        _cart.AddItem("B", 10.00m, 1);
        _cart.RegisterPromoCode("TEN", 10);
        _cart.ApplyPromoCode("TEN");
        // Subtotal 50, 10% off = 45
        Assert.AreEqual(45.00m, _cart.GetTotal());
    }
}

